 "content": "from collections import Counter


def transform(grid):
    """Fill single-cell horizontal gaps between matching non-background markers with 2."""
    if not grid:
        return []
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            marker = row[c - 1]
            if marker != background and row[c + 1] == marker and row[c] == background:
                out[r][c] = 2
    return out
